script.setup:
// SunCalc gives the sun's (and moon's) altitude and azimuth for a place and time; a raymarched
// plaza is lit from there, with the sky, shadows and the day's sun path following it.
const mod = await ctx.utils.import("https://esm.sh/suncalc@2.0.2");
const SunCalc = mod.default ?? mod;
const CITIES = [["Seoul", 37.57, 126.98], ["Reykjavík", 64.15, -21.94], ["Singapore", 1.35, 103.82], ["Sydney", -33.87, 151.21], ["Tromsø", 69.65, 18.96], ["Quito", -0.18, -78.47]];
const program = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform vec2 u_resolution; uniform vec3 u_sun; uniform vec3 u_moon; uniform vec3 u_path[96]; uniform vec3 u_eye; uniform vec3 u_target; uniform float u_tanHalf; uniform float u_time;
float sdBox(vec3 p, vec3 b) { vec3 q = abs(p) - b; return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0); }
float map(vec3 p) {
  float d = p.y;
  // The obelisk (a gnomon) in the middle, with a pointed cap.
  d = min(d, sdBox(p - vec3(0, 2.6, 0), vec3(0.35, 2.6, 0.35)));
  vec3 q = p - vec3(0, 5.2, 0);
  d = min(d, max(sdBox(q, vec3(0.35, 0.6, 0.35)), (abs(q.x) + abs(q.z)) * 0.86 + q.y * 0.6 - 0.3));
  // A ring of columns with lintels on every other pair.
  float a = atan(p.z, p.x), sector = 6.2831853 / 10.0;
  float k = floor(a / sector + 0.5);
  vec3 c = p; float ang = k * sector;
  c.xz = mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * c.xz; // rotate by -ang
  d = min(d, sdBox(c - vec3(6.5, 1.3, 0), vec3(0.35, 1.3, 0.35)));
  if (mod(k, 2.0) < 0.5) {
    float ang2 = (k + 0.5) * sector; vec3 l = p;
    l.xz = mat2(cos(ang2), -sin(ang2), sin(ang2), cos(ang2)) * l.xz;
    d = min(d, sdBox(l - vec3(6.45, 2.75, 0), vec3(0.45, 0.18, 2.3)));
  }
  // A low plinth around the obelisk.
  d = min(d, sdBox(p - vec3(0, 0.12, 0), vec3(1.4, 0.12, 1.4)) - 0.02);
  return d;
}
vec3 normal(vec3 p) { vec2 e = vec2(0.002, 0); return normalize(vec3(map(p + e.xyy) - map(p - e.xyy), map(p + e.yxy) - map(p - e.yxy), map(p + e.yyx) - map(p - e.yyx))); }
float shadow(vec3 ro, vec3 rd) {
  float res = 1.0, t = 0.05;
  for (int i = 0; i < 64; i++) { float h = map(ro + rd * t); res = min(res, 10.0 * h / t); t += clamp(h, 0.03, 0.6); if (res < 0.002 || t > 40.0) break; }
  return clamp(res, 0.0, 1.0);
}
vec3 skyColor(vec3 rd) {
  float alt = u_sun.y;
  float day = smoothstep(-0.12, 0.25, alt), dusk = exp(-abs(alt) * 7.0);
  vec3 zenith = mix(vec3(0.01, 0.015, 0.04), vec3(0.18, 0.4, 0.8), day);
  vec3 horizon = mix(vec3(0.03, 0.04, 0.08), vec3(0.65, 0.8, 0.95), day);
  vec3 col = mix(horizon, zenith, pow(clamp(rd.y, 0.0, 1.0), 0.5));
  float toSun = max(dot(rd, normalize(u_sun)), 0.0);
  col += vec3(1.0, 0.45, 0.15) * dusk * pow(toSun, 3.0) * 0.9 * (1.0 - clamp(rd.y * 2.0, 0.0, 1.0));
  col += vec3(1.0, 0.8, 0.55) * pow(toSun, 300.0) * day * 0.6;
  // Stars when the sun is well below the horizon.
  vec3 cell = floor(rd * 160.0);
  float star = step(0.9975, fract(sin(dot(cell, vec3(12.9898, 78.233, 37.719))) * 43758.5453));
  col += star * (1.0 - smoothstep(-0.2, -0.05, alt)) * 0.8 * smoothstep(0.0, 0.1, rd.y);
  return col;
}
void main(){
  vec2 uv = (v_uv - 0.5) * u_resolution / u_resolution.y;
  // The shared orbit camera; it starts north of the plaza looking south (east on the left).
  vec3 ro = u_eye, ta = u_target;
  vec3 fw = normalize(ta - ro), rt = normalize(cross(fw, vec3(0, 1, 0))), up = cross(rt, fw);
  vec3 rd = normalize(fw + (uv.x * rt + uv.y * up) * 2.0 * u_tanHalf);
  vec3 sun = normalize(u_sun), col;
  float t = 0.0; bool hit = false;
  for (int i = 0; i < 128; i++) { float d = map(ro + rd * t); if (d < 0.001) { hit = true; break; } t += d; if (t > 80.0) break; }
  if (hit) {
    vec3 p = ro + rd * t, n = normal(p);
    float day = smoothstep(-0.05, 0.1, sun.y);
    vec3 sunCol = mix(vec3(1.0, 0.45, 0.2), vec3(1.0, 0.95, 0.88), smoothstep(0.0, 0.5, sun.y)) * 2.4 * day;
    vec3 albedo = p.y < 0.01 ? vec3(0.72, 0.62, 0.48) : vec3(0.8, 0.76, 0.7);
    // Paving: thin joints every 1.5 units.
    if (p.y < 0.01) { vec2 g = abs(fract(p.xz / 1.5) - 0.5); albedo *= 0.85 + 0.15 * smoothstep(0.47, 0.44, max(g.x, g.y)); }
    float diff = max(dot(n, sun), 0.0) * (day > 0.0 ? shadow(p + n * 0.01, sun) : 0.0);
    vec3 amb = skyColor(normalize(n + vec3(0, 1, 0))) * 0.75 + 0.025;
    // Moonlight, faint and blue.
    float moon = max(dot(n, normalize(u_moon)), 0.0) * smoothstep(0.0, 0.1, u_moon.y) * (1.0 - day) * 0.12;
    col = albedo * (sunCol * diff + amb + vec3(0.5, 0.6, 0.9) * moon);
    col = mix(col, skyColor(rd), 1.0 - exp(-t * 0.012));
  } else {
    col = skyColor(rd);
    col = mix(col, vec3(1.0, 0.97, 0.9) * 3.0, smoothstep(0.9993, 0.9996, dot(rd, sun)));
    col = mix(col, vec3(0.85, 0.88, 0.95), smoothstep(0.99975, 0.9999, dot(rd, normalize(u_moon))) * step(0.0, u_moon.y));
    // The day's sun path: a dot every 15 minutes, bigger on the hour.
    for (int i = 0; i < 96; i++) {
      vec3 pd = u_path[i];
      if (pd.y < -0.02) continue;
      float ang = acos(clamp(dot(rd, normalize(pd)), -1.0, 1.0)), r = (i % 4 == 0) ? 0.0045 : 0.0025;
      col += vec3(1.0, 0.85, 0.5) * (0.6 * smoothstep(r, r * 0.6, ang) + 0.08 * exp(-ang * 150.0));
    }
  }
  col = 1.0 - exp(-col * 1.1);
  outColor = vec4(pow(col, vec3(0.9)), 1.0);
}`);
const dir = (p) => { const alt = p.altitude * Math.PI / 180, az = p.azimuth * Math.PI / 180; return [Math.cos(alt) * Math.sin(az), Math.sin(alt), -Math.cos(alt) * Math.cos(az)]; };
Object.assign(ctx.state, { SunCalc, CITIES, program, dir, key: "", path: new Float32Array(96 * 3), 
  // 74° vertical field of view; orbit around the obelisk's upper half.
  camera: ctx.utils.createOrbitCamera({ distance: 15.26, theta: Math.PI, phi: 1.755, target: [0, 5.8, 0], fov: 74, minDistance: 3, maxDistance: 45 }) });

script.render:
const s = ctx.state, u = ctx.uniforms, S = s.SunCalc;
const [name, lat, lng] = s.CITIES[u.u_city] ?? s.CITIES[0];
// Local solar time: UTC hour = solar hour - longitude / 15.
const hour = ((u.u_hour + ctx.time * u.u_speed) % 24 + 24) % 24;
const at = (h) => new Date(Date.UTC(2026, 0, u.u_day) + (h - lng / 15) * 3.6e6);
const key = [u.u_city, u.u_day].join();
if (key !== s.key) {
  s.key = key;
  for (let i = 0; i < 96; i++) s.path.set(s.dir(S.getPosition(at(i / 4), lat, lng)), i * 3);
  const times = S.getTimes(at(12), lat, lng);
  const solar = (d) => { if (!d || isNaN(d)) return "—"; const h = ((d.getTime() / 3.6e6 + lng / 15) % 24 + 24) % 24; return `${String(Math.floor(h)).padStart(2, "0")}:${String(Math.floor(h % 1 * 60)).padStart(2, "0")}`; };
  ctx.publish("sunrise", solar(times.sunrise));
  ctx.publish("sunset", solar(times.sunset));
}
const sun = S.getPosition(at(hour), lat, lng), moon = S.getMoonPosition(at(hour), lat, lng);
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
// Keep the eye above the paving so the camera never starts inside the ground.
const eye = s.camera.getEye();
eye[1] = Math.max(eye[1], 0.3);
const gl = ctx.gl;
gl.useProgram(s.program);
ctx.utils.drawFullscreen(s.program, { u_sun: s.dir(sun), u_moon: s.dir(moon), u_path: s.path, u_eye: eye, u_target: s.camera.getTarget(), u_tanHalf: Math.tan(s.camera.fov * Math.PI / 360) });
ctx.publish("place", name);
ctx.publish("solar time", `${String(Math.floor(hour)).padStart(2, "0")}:${String(Math.floor(hour % 1 * 60)).padStart(2, "0")}`);
ctx.publish("sun altitude °", +sun.altitude.toFixed(1));
ctx.publish("sun azimuth °", +sun.azimuth.toFixed(1));
